draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // dog body
  ctx.beginPath();
  ctx.moveTo(W/2 + 20*Math.sin(t), H/2);
  ctx.lineTo(W/2 + 20*Math.sin(t) - 30, H/2 + 50);
  ctx.stroke();

  // dog head
  ctx.beginPath();
  ctx.arc(W/2 + 20*Math.sin(t), H/2 - 30, 20, 0, 2*Math.PI);
  ctx.stroke();

  // dog ear
  ctx.beginPath();
  ctx.moveTo(W/2 + 20*Math.sin(t) - 10, H/2 - 50);
  ctx.lineTo(W/2 + 20*Math.sin(t) - 20, H/2 - 70);
  ctx.stroke();

  // dog leg
  ctx.beginPath();
  ctx.moveTo(W/2 + 20*Math.sin(t) - 15, H/2 + 50);
  ctx.lineTo(W/2 + 20*Math.sin(t) - 30, H/2 + 80);
  ctx.stroke();

  // dog tail
  ctx.beginPath();
  ctx.moveTo(W/2 + 20*Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 20*Math.sin(t) + 30 + 20*Math.cos(t), H/2 + 70);
  ctx.stroke();

  ctx.restore();
}
